/**
 * CostBreakdownTable — BATCH-18/TASK-02
 *
 * Renders a table from a dict breakdown (by-provider, by-stage, by-model).
 * Uses Object.entries() to convert the dict into table rows.
 */

import type { BreakdownEntry } from "@/api/costs";

interface CostBreakdownTableProps {
  title: string;
  data: Record<string, BreakdownEntry>;
  labelColumn?: string;
}

function formatUSD(value: number): string {
  return `$${value.toFixed(4)}`;
}

function formatNumber(value: number): string {
  return value.toLocaleString();
}

export function CostBreakdownTable({
  title,
  data,
  labelColumn = "Name",
}: CostBreakdownTableProps) {
  const entries = Object.entries(data);

  if (entries.length === 0) {
    return (
      <div className="rounded-lg border bg-card p-6" data-testid="cost-breakdown-table">
        <h3 className="text-sm font-medium text-muted-foreground mb-2">{title}</h3>
        <p className="text-sm text-muted-foreground">No data available.</p>
      </div>
    );
  }

  return (
    <div className="rounded-lg border bg-card p-6" data-testid="cost-breakdown-table">
      <h3 className="text-sm font-medium text-muted-foreground mb-4">{title}</h3>
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b text-left text-muted-foreground">
              <th className="pb-2 pr-4 font-medium">{labelColumn}</th>
              <th className="pb-2 pr-4 font-medium text-right">Cost (USD)</th>
              <th className="pb-2 pr-4 font-medium text-right">Input Tokens</th>
              <th className="pb-2 pr-4 font-medium text-right">Output Tokens</th>
              <th className="pb-2 font-medium text-right">Calls</th>
            </tr>
          </thead>
          <tbody>
            {entries.map(([name, entry]) => (
              <tr key={name} className="border-b last:border-0">
                <td className="py-2 pr-4 font-medium">{name}</td>
                <td className="py-2 pr-4 text-right">{formatUSD(entry.cost_usd)}</td>
                <td className="py-2 pr-4 text-right">{formatNumber(entry.input_tokens)}</td>
                <td className="py-2 pr-4 text-right">{formatNumber(entry.output_tokens)}</td>
                <td className="py-2 text-right">{formatNumber(entry.calls)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/**
 * BudgetBar — BATCH-18/TASK-02
 *
 * Visualizes budget utilization as a progress bar.
 * Shows current spend vs. configured budget limit.
 */

interface BudgetBarProps {
  currentSpend: number;
  budgetLimit: number;
}

function formatUSD(value: number): string {
  return `$${value.toFixed(2)}`;
}

export function BudgetBar({ currentSpend, budgetLimit }: BudgetBarProps) {
  const pct = budgetLimit > 0 ? Math.min((currentSpend / budgetLimit) * 100, 100) : 0;
  const isOverBudget = currentSpend > budgetLimit && budgetLimit > 0;

  const barColor = isOverBudget
    ? "bg-red-500"
    : pct > 80
      ? "bg-yellow-500"
      : "bg-green-500";

  return (
    <div className="rounded-lg border bg-card p-6" data-testid="budget-bar">
      <div className="flex items-center justify-between mb-2">
        <h3 className="text-sm font-medium text-muted-foreground">Budget Utilization</h3>
        <span className="text-sm font-medium" data-testid="budget-percentage">
          {pct.toFixed(1)}%
        </span>
      </div>
      <div className="h-3 w-full rounded-full bg-muted overflow-hidden">
        <div
          className={`h-full rounded-full transition-all ${barColor}`}
          style={{ width: `${pct}%` }}
          data-testid="budget-bar-fill"
        />
      </div>
      <div className="flex justify-between mt-2 text-xs text-muted-foreground">
        <span data-testid="budget-current">{formatUSD(currentSpend)} spent</span>
        <span data-testid="budget-limit">{formatUSD(budgetLimit)} limit</span>
      </div>
    </div>
  );
}

